Object.assign(titles,{atlas:'Scientist atlas',games:'Physics arcade',discovery:'Animated discovery'});
const scientists=[
{id:'newton',name:'Isaac Newton',field:'GRAVITY',glyph:'F = ma',title:'A universe in motion',formula:'F = Gm₁m₂ / r²',desc:'Gravity bends a moving body’s path into an orbit. Stretch this ellipse and watch the body accelerate near the central mass.',kind:'orbit',label:'Eccentricity',min:0,max:.8,step:.01,value:.42},
{id:'galileo',name:'Galileo Galilei',field:'FALLING BODIES',glyph:'½gt²',title:'Two masses. One fall.',formula:'s = ½gt²',desc:'Without air resistance, bodies fall with the same gravitational acceleration regardless of their mass. Change the blue body’s mass; both still land together.',kind:'fall',label:'Blue mass',min:1,max:10,step:1,value:5},
{id:'kepler',name:'Johannes Kepler',field:'PLANETARY MOTION',glyph:'T² ∝ a³',title:'Fast near. Slow far.',formula:'Equal areas in equal times',desc:'A planet travels faster near its star and slower farther away. Kepler’s second law connects this changing speed to conservation of angular momentum.',kind:'orbit',label:'Eccentricity',min:0,max:.8,step:.01,value:.65},
{id:'hooke',name:'Robert Hooke',field:'ELASTICITY',glyph:'−kx',title:'The pull back to equilibrium',formula:'F = −kx  ·  ω = √(k/m)',desc:'Stretch a spring and its restoring force points back toward equilibrium. With fixed mass, a stiffer spring oscillates faster in this ideal model.',kind:'spring',label:'Stiffness',min:.5,max:4,step:.1,value:1.4},
{id:'coulomb',name:'Charles Coulomb',field:'ELECTRIC FIELDS',glyph:'q₁q₂ / r²',title:'Invisible forces, visible patterns',formula:'F = kq₁q₂ / r²',desc:'A positive and a negative charge form a dipole. The arrows show the direction of the electric field. Change their separation to reshape it.',kind:'field',label:'Separation',min:.3,max:1,step:.05,value:.6},
{id:'ampere',name:'André-Marie Ampère',field:'MAGNETISM',glyph:'∮B · dl',title:'A current makes a circle',formula:'B = μ₀I / (2πr)',desc:'A long straight current-carrying wire has a magnetic field that circles it. Here the field direction follows the right-hand rule for current out of the screen.',kind:'magnetic',label:'Current',min:.4,max:2,step:.1,value:1},
{id:'faraday',name:'Michael Faraday',field:'INDUCTION',glyph:'−dΦ / dt',title:'Motion becomes electricity',formula:'ε = −dΦB / dt',desc:'A changing magnetic flux induces an electromotive force. The purple flux trace and gold voltage trace are shifted in phase. Faster flux changes produce a larger voltage.',kind:'induction',label:'Frequency',min:.3,max:2,step:.1,value:1},
{id:'maxwell',name:'James Clerk Maxwell',field:'ELECTROMAGNETISM',glyph:'E ⊥ B',title:'Light is a traveling conversation',formula:'c = 1 / √(μ₀ε₀)',desc:'An electromagnetic wave carries electric and magnetic fields perpendicular to each other and its direction of travel. Both fields are scaled here for visibility.',kind:'em',label:'Amplitude',min:.2,max:1,step:.05,value:.7},
{id:'hertz',name:'Heinrich Hertz',field:'RADIO WAVES',glyph:'λf = c',title:'Waves beyond what we see',formula:'v = fλ',desc:'Hertz demonstrated electromagnetic waves experimentally. In this traveling-wave model the speed stays fixed: raising frequency shortens wavelength.',kind:'travel',label:'Frequency',min:1,max:5,step:.1,value:2},
{id:'huygens',name:'Christiaan Huygens',field:'WAVEFRONTS',glyph:')))',title:'Every point starts a wave',formula:'A wavefront is an envelope of wavelets',desc:'Each point on an advancing wavefront can be treated as a source of secondary wavelets. Watch their circular fronts combine into an advancing envelope.',kind:'wavelets',label:'Wave speed',min:.5,max:2,step:.1,value:1},
{id:'young',name:'Thomas Young',field:'INTERFERENCE',glyph:'∿ + ∿',title:'Light meets light',formula:'I ∝ cos²(πd sinθ / λ)',desc:'Two coherent slits produce alternating bright and dark fringes. Greater slit separation brings the bright fringes closer together. A finite slit width shapes the envelope.',kind:'interference',label:'Slit separation',min:2,max:8,step:.1,value:4},
{id:'doppler',name:'Christian Doppler',field:'RELATIVE MOTION',glyph:'f → f′',title:'The sound of getting closer',formula:'f′ = f · v / (v − vₛ)',desc:'For a source moving toward a stationary observer in a medium, wavefronts bunch up ahead and spread out behind. This scene stays below the wave speed.',kind:'doppler',label:'Source speed / wave speed',min:0,max:.7,step:.05,value:.4},
{id:'einstein',name:'Albert Einstein',field:'RELATIVITY',glyph:'γ',title:'A clock made of light',formula:'Δt = γΔτ  ·  γ = 1 / √(1 − v²/c²)',desc:'A light clock moving relative to an observer ticks more slowly in that observer’s frame. Compare its ticks with a stationary clock as you increase speed.',kind:'clock',label:'Speed / c',min:0,max:.95,step:.01,value:.7},
{id:'planck',name:'Max Planck',field:'QUANTIZATION',glyph:'E = hν',title:'The color of temperature',formula:'λmaxT ≈ 2.898 × 10⁻³ m·K',desc:'Planck’s blackbody law describes thermal radiation. Heat the ideal emitter and the peak moves to shorter wavelengths. Curves are normalized to compare their shape.',kind:'spectrum',label:'Temperature (K)',min:3000,max:10000,step:100,value:5500},
{id:'bohr',name:'Niels Bohr',field:'ATOMIC ENERGY',glyph:'ΔE = hν',title:'An atom changes its tune',formula:'Eₙ = −13.6 eV / n²',desc:'In Bohr’s historical hydrogen model, electrons occupy discrete energies. A transition to a lower level releases a photon. This is an energy-level diagram, not an electron’s literal path.',kind:'levels',label:'Initial energy level n',min:2,max:5,step:1,value:3},
{id:'curie',name:'Marie Curie',field:'RADIOACTIVITY',glyph:'N₀e⁻λt',title:'Order inside randomness',formula:'N(t) = N₀ · 2^(−t / t½)',desc:'Curie’s work established radioactivity as a property of atoms. Individual decay times are unpredictable, while a large population follows an exponential pattern.',kind:'decay',label:'Half-life (seconds)',min:1,max:6,step:.5,value:3},
{id:'rutherford',name:'Ernest Rutherford',field:'THE ATOMIC NUCLEUS',glyph:'α ↗',title:'Mostly empty. A dense center.',formula:'Coulomb scattering',desc:'Rutherford scattering revealed a compact atomic nucleus. These qualitative trajectories show positively charged probes deflecting around a repulsive nucleus; closer passes bend more.',kind:'scattering',label:'Repulsion',min:.3,max:1.5,step:.1,value:.8},
{id:'schrodinger',name:'Erwin Schrödinger',field:'WAVE MECHANICS',glyph:'ψ',title:'A wave of possibility',formula:'iℏ ∂ψ/∂t = Ĥψ',desc:'A free Gaussian wave packet spreads as it travels. The curve shows probability density |ψ|², not a particle smeared into a classical material. Units are normalized.',kind:'packet',label:'Initial packet width',min:.4,max:1.5,step:.1,value:.8},
{id:'feynman',name:'Richard Feynman',field:'QUANTUM AMPLITUDES',glyph:'Σ eiS/ℏ',title:'Add the arrows, then square',formula:'P ∝ |Σ Aⱼ|²',desc:'Quantum alternatives contribute complex amplitudes. Represent them as arrows: alignment builds a large sum; opposing phases cancel. The probability depends on the squared magnitude of their sum.',kind:'phasors',label:'Phase step',min:0,max:180,step:1,value:35},
{id:'noether',name:'Emmy Noether',field:'SYMMETRY',glyph:'↻ → L',title:'A symmetry keeps a promise',formula:'Rotational symmetry → angular momentum conservation',desc:'Noether connected continuous symmetries to conserved quantities. An isolated central-force orbit has no preferred direction. Rotate the entire orbit without changing its dynamics.',kind:'symmetry',label:'Rotate the system (°)',min:0,max:180,step:1,value:25},
{id:'bose',name:'Satyendra Nath Bose',field:'QUANTUM STATISTICS',glyph:'n̄B',title:'Particles that share a state',formula:'n̄ = 1 / [exp((E − μ)/kT) − 1]',desc:'Bose’s statistics allow identical bosons to share a quantum state. These bars show mean occupation for fixed energy levels and a fixed negative chemical potential as temperature changes.',kind:'bose',label:'Temperature (normalized)',min:.3,max:3,step:.1,value:1.2},
{id:'raman',name:'C. V. Raman',field:'LIGHT SCATTERING',glyph:'ν → ν − νv',title:'Light returns with a clue',formula:'νStokes = νincident − νvibration',desc:'Most scattered photons keep their frequency. A small fraction exchange energy with molecular vibrations. The shifted Raman lines reveal information about the material.',kind:'raman',label:'Vibrational shift',min:.3,max:1,step:.05,value:.65},
{id:'boltzmann',name:'Ludwig Boltzmann',field:'STATISTICAL PHYSICS',glyph:'S = k ln Ω',title:'Temperature is a crowd story',formula:'fr(v) ∝ v² exp(−mv² / 2kT)',desc:'The Maxwell–Boltzmann speed distribution describes a classical ideal gas at equilibrium. Higher temperature shifts and broadens the distribution. Speeds and temperature are normalized.',kind:'gas',label:'Temperature',min:.4,max:2.5,step:.1,value:1},
{id:'dirac',name:'Paul Dirac',field:'RELATIVISTIC QUANTUM THEORY',glyph:'±E',title:'Two branches of energy',formula:'E² = p²c² + m²c⁴',desc:'Dirac’s relativistic quantum theory helped lead to the prediction of antimatter. These positive and negative energy branches illustrate the relativistic dispersion relation; they are not particle trajectories.',kind:'dirac',label:'Mass (normalized)',min:.2,max:1.5,step:.1,value:.7}
];
let discovery=null,discoveryTime=0,discoveryPaused=false;let badges={};try{badges=JSON.parse(localStorage.getItem('curiosity-passport-v1')||'{}')}catch{}
function updatePassport(){const earned=['newton','faraday','maxwell','feynman'].filter(k=>badges[k]);document.querySelector('#badge-count').textContent=earned.length;document.querySelectorAll('#badge-row span').forEach((e,i)=>e.classList.toggle('earned',!!badges[['newton','faraday','maxwell','feynman'][i]]))}updatePassport();
function award(id){badges[id]=true;try{localStorage.setItem('curiosity-passport-v1',JSON.stringify(badges))}catch{}updatePassport()}
const oldRender=renderApp;renderApp=function(id,el){if(id==='atlas'||id==='discovery')renderAtlas(el);else if(id==='games')renderGames(el);else if(id==='experience')renderExperience(el);else if(id==='about')renderAbout(el);else oldRender(id,el)};
function renderExperience(el){el.innerHTML=`<span class="eyebrow">AI ENGINEER / PHYSICS ENTHUSIAST</span><h2>Building intelligence<br>for real-world systems.</h2><div class="experience-entry"><span class="meta">RTIFACT · NOV 2025 — PRESENT · REMOTE</span><h3>Associate ML Engineer</h3><p>Production AI that helps engineering and operations teams investigate incidents, connect evidence, and make safer remediation decisions.</p></div><div class="experience-work"><article class="work-item"><h3>An AI operations platform</h3><p>Built and extended a platform connecting alerts, logs, metrics, traces, Kubernetes state, Git changes, and runbooks into grounded investigations.</p></article><article class="work-item"><h3>MCP Forge & operational agents</h3><p>Implemented capabilities for ArgoCD, GitHub, and Kubernetes: failure triage, topology discovery, live log streaming, root-cause analysis, and approval-gated actions.</p></article><article class="work-item"><h3>Finding issues before the page</h3><p>Developed proactive monitoring with anomaly scores, multi-signal evidence, confidence gates, and LLM agents to catch rising issues before threshold-based paging.</p></article><article class="work-item"><h3>Tools built for production</h3><p>Built reusable MCP, Agno, and LiteLLM toolsets with tenant scoping, persistent sessions, audit logs, request tracing, and GitLab change correlation.</p></article><article class="work-item"><h3>Observability & incident enrichment</h3><p>Created Prometheus alert rules and runbooks with CI validation and synthetic tests. Automated support-case and delivery-incident enrichment using RAG, Kafka, MongoDB, Athena, Graylog, NRQL, and AWS Bedrock.</p></article></div><div>${['AI agents','MCP','RAG','Kubernetes','ArgoCD','Prometheus','VictoriaMetrics','VictoriaLogs','New Relic','FastAPI','Kafka','PostgreSQL','MongoDB','AWS Bedrock'].map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="detail-actions"><button class="primary" data-open="projects">Explore selected projects</button><a href="https://www.linkedin.com/in/sudhanshu-bhale" target="_blank" rel="noopener">LinkedIn profile</a></div>`}
function renderAbout(el){el.innerHTML=`<div class="profile-intro"><img src="assets/sudhanshu-pixel.png" alt="Pixel-art portrait of Sudhanshu"><div><span class="meta">THE HUMAN BEHIND THE UNIVERSE</span><h2>Sudhanshu Bhale.</h2><p>AI engineer. Physics enthusiast.<br>Pune, India.</p></div></div><p>I build production AI systems at Rtifact. My day-to-day work connects agents, observability, backend engineering, and cloud-native systems.</p><p>Physics is my enduring curiosity. This little universe is an invitation to explore it together: change something, notice a pattern, ask a better question.</p><div class="achievement"><strong>100 percentile · Physics</strong><p>JEE Main · March 2021 attempt</p></div><div class="experience-entry"><span class="meta">FOUNDATIONS</span><h3>Indian Institute of Information Technology Vadodara</h3></div><div class="detail-actions"><button class="primary" data-open="experience">The engineering side</button><button data-open="games">Back to the adventure</button></div>`}
function renderAtlas(el){el.innerHTML=`<span class="eyebrow">THE OBSERVATORY / 24 WINDOWS INTO NATURE</span><h2>Great questions live on.</h2><p>Pick a scientist. Watch their idea move. Change a parameter and see what follows.</p><input class="search atlas-search" type="search" aria-label="Find a scientist" placeholder="A name, a discovery, a little curiosity…"><div class="atlas-grid"></div>`;const input=el.querySelector('input');function filter(){const q=input.value.toLowerCase();el.querySelector('.atlas-grid').innerHTML=scientists.filter(s=>[s.name,s.field,s.title].join(' ').toLowerCase().includes(q)).map(s=>`<button class="scientist-card" data-scientist="${s.id}"><span class="glyph">${s.glyph}</span><h3>${s.name}</h3><small>${s.title}</small><span class="meta">${s.field} ＋</span></button>`).join('')||'<p>No discoveries match yet. Try “light” or “quantum”.</p>'}input.oninput=filter;filter()}
function openScientist(id){const s=scientists.find(s=>s.id===id);if(!s)return;discovery={...s};discoveryTime=0;discoveryPaused=false;let w=openApp('discovery'),el=w.querySelector('.window-content');el.innerHTML=`<div class="atlas-nav"><button data-open="atlas">‹ Scientist atlas</button><button id="next-scientist">Next discovery ›</button></div><span class="eyebrow">${s.name.toUpperCase()} / ${s.field}</span><h2>${s.title}</h2><canvas class="scientist-view" id="science-canvas" aria-label="Animated demonstration: ${s.title}"></canvas><div class="science-controls"><label>${s.label}<input id="science-range" type="range" min="${s.min}" max="${s.max}" step="${s.step}" value="${s.value}"><output id="science-value">${s.value}</output></label><button class="filter" id="science-pause">Pause</button><button class="filter" id="science-reset">Reset</button></div><div class="science-formula">${s.formula}</div><p>${s.desc}</p><p class="science-note">An educational visualization. Scale, colors, and time are simplified; illustrations are not portraits of the original experiments.</p>${['newton','faraday','maxwell','feynman'].includes(id)?`<button class="primary" data-game="${id}">Play the ${s.name.split(' ').at(-1)} challenge</button>`:''}`;el.scrollTop=0;el.querySelector('#science-range').oninput=e=>{discovery.value=+e.target.value;el.querySelector('#science-value').value=e.target.value};el.querySelector('#science-pause').onclick=e=>{discoveryPaused=!discoveryPaused;e.target.textContent=discoveryPaused?'Resume':'Pause'};el.querySelector('#science-reset').onclick=()=>openScientist(id);el.querySelector('#next-scientist').onclick=()=>openScientist(scientists[(scientists.indexOf(s)+1)%scientists.length].id)}
document.addEventListener('click',e=>{const s=e.target.closest('[data-scientist]');if(s)openScientist(s.dataset.scientist);const g=e.target.closest('[data-game]');if(g)openGame(g.dataset.game)});
const drawOldLab=drawLab;drawLab=function(dt){drawOldLab(dt);drawDiscovery(dt);drawGame(dt)};
function plotFrame(c){let[w,h,x]=fit(c);x.clearRect(0,0,w,h);x.strokeStyle='#9580b41b';x.lineWidth=1;for(let i=25;i<w;i+=32){x.beginPath();x.moveTo(i,20);x.lineTo(i,h-20);x.stroke()}for(let i=25;i<h;i+=32){x.beginPath();x.moveTo(20,i);x.lineTo(w-20,i);x.stroke()}x.font='12px monospace';return[w,h,x]}
function dot(x,a,b,r,color){x.fillStyle=color;x.beginPath();x.arc(a,b,r,0,Math.PI*2);x.fill()}
function line(x,ax,ay,bx,by,color='#bba0e4',width=2){x.strokeStyle=color;x.lineWidth=width;x.beginPath();x.moveTo(ax,ay);x.lineTo(bx,by);x.stroke()}
function label(x,text,a,b,color='#b9abc9'){x.fillStyle=color;x.font='12px monospace';x.fillText(text,a,b)}
function path(x,fn,w,h,color='#d4b6ff',left=30,right=w-30){x.strokeStyle=color;x.lineWidth=2;x.beginPath();for(let px=left;px<=right;px++){const py=fn((px-left)/(right-left));px===left?x.moveTo(px,py):x.lineTo(px,py)}x.stroke()}
function drawDiscovery(dt){const c=document.querySelector('#science-canvas');if(!c||!discovery||wins.get('discovery')?.hidden)return;if(!paused&&!discoveryPaused)discoveryTime+=dt;const s=discovery,v=s.value,t=discoveryTime;let[w,h,x]=plotFrame(c),cx=w/2,cy=h/2;const gold='#e5cb86',purple='#cbb1f4',teal='#91d3cb';
if(s.kind==='orbit'){drawOrbit(c,t*.7,v);return}
if(s.kind==='fall'){const tt=t%3.4,p=Math.min(1,(tt/2.5)**2);line(x,35,h-40,w-35,h-40,'#718397');for(let n=0;n<2;n++){let a=w*(n?.68:.32),r=12;dot(x,a,45+p*(h-85-r),r,n?teal:gold);label(x,n?v+' kg':'1 kg',a-20,25);label(x,'same g',a-25,h-16)}return}
if(s.kind==='spring'){let pos=cx+Math.cos(t*Math.sqrt(v)*3)*w*.2;line(x,35,cy,65,cy);x.strokeStyle=purple;x.beginPath();x.moveTo(65,cy);for(let i=0;i<30;i++)x.lineTo(65+(pos-85)*i/29,cy+(i%2?12:-12));x.stroke();x.fillStyle=gold;x.fillRect(pos-14,cy-20,40,40);line(x,30,cy+24,w-25,cy+24,'#5c506c');label(x,'equilibrium',cx-38,cy+60);return}
if(s.kind==='field'){let d=w*.25*v;for(let a=30;a<w-25;a+=25)for(let b=35;b<h-25;b+=25){let ex=0,ey=0;for(let q of [-1,1]){let dx=a-(cx-q*d),dy=b-cy,r2=dx*dx+dy*dy+70;ex+=q*dx/r2**1.5;ey+=q*dy/r2**1.5}let angle=Math.atan2(ey,ex),len=8;line(x,a,b,a+Math.cos(angle)*len,b+Math.sin(angle)*len,'#a89cb5',1);let flow=(t*.8+(a+b)/160)%1;dot(x,a+Math.cos(angle)*len*flow,b+Math.sin(angle)*len*flow,1.4,'#d2bcf0');line(x,a+Math.cos(angle)*len,b+Math.sin(angle)*len,a+Math.cos(angle)*len-Math.cos(angle-.6)*4,b+Math.sin(angle)*len-Math.sin(angle-.6)*4,'#a89cb5',1)}dot(x,cx-d,cy,12,gold);dot(x,cx+d,cy,12,teal);label(x,'+',cx-d-4,cy+4,'#171322');label(x,'−',cx+d-4,cy+4,'#171322');return}
if(s.kind==='magnetic'){dot(x,cx,cy,9,gold);for(let i=1;i<=4;i++){let r=Math.min(w,h)*.09*i;x.strokeStyle=purple+'77';x.beginPath();x.arc(cx,cy,r,0,7);x.stroke();let a=-t*v/i;dot(x,cx+r*Math.cos(a),cy+r*Math.sin(a),3+v,teal)}label(x,'I out of screen · B circles counterclockwise',20,h-17);return}
if(s.kind==='induction'){path(x,u=>cy-Math.sin(u*12.56+t*v)*h*.21,w,h,purple);path(x,u=>cy+v*Math.cos(u*12.56+t*v)*h*.18,w,h,gold);label(x,'flux Φ',30,28,purple);label(x,'induced ε',30,47,gold);return}
if(s.kind==='em'){for(let n=0;n<2;n++){x.strokeStyle=n?gold:teal;x.beginPath();for(let a=0;a<w-60;a++){let y=Math.sin(a/(w-60)*12.56-t*2)*h*.28*v,xx=30+a+(n?y*.3:0),yy=cy+y*(n?.4:-1);a?x.lineTo(xx,yy):x.moveTo(xx,yy)}x.stroke()}label(x,'E field',30,28,teal);label(x,'B field (scaled)',30,47,gold);label(x,'propagation +x',w-145,h-18);return}
if(s.kind==='travel'){path(x,u=>cy-Math.sin((u-t*.13)*Math.PI*2*v)*h*.25,w,h,teal);label(x,'fixed speed · more frequency = shorter wavelength',25,25);return}
if(s.kind==='wavelets'){for(let i=0;i<7;i++){let y=40+i*(h-80)/6;dot(x,50,y,3,gold);for(let n=0;n<3;n++){let r=((t*v*28+n*70)%(w-90));x.strokeStyle=purple+'77';x.beginPath();x.arc(50,y,r,-Math.PI/2,Math.PI/2);x.stroke()}}label(x,'secondary wavelets',22,h-13);return}
if(s.kind==='interference'){let base=h-30;for(let a=30;a<w-30;a++){let u=((a-30)/(w-60)-.5)*3,z=Math.PI*.7*u,env=Math.abs(z)<.001?1:(Math.sin(z)/z)**2,I=env*Math.cos(Math.PI*v*u)**2;x.fillStyle=`rgba(211,186,255,${.05+I*.95})`;x.fillRect(a,35,1,50)}path(x,u=>{let z=(u-.5)*3,q=Math.PI*.7*z,env=Math.abs(q)<.001?1:(Math.sin(q)/q)**2;return base-env*Math.cos(Math.PI*v*z)**2*(h-145)},w,h,gold);let a=30+(t*.1%1)*(w-60);line(x,a,28,a,h-25,'#d3f2e033',1);return}
if(s.kind==='doppler'){let speed=v*45,period=7,tt=t%period,start=w*.15,source=start+tt*speed;for(let born=0;born<tt;born+=.45){let r=(tt-born)*45,xx=start+born*speed;x.strokeStyle=purple+'99';x.beginPath();x.arc(xx,cy,r,0,7);x.stroke()}dot(x,source,cy,7,gold);label(x,'moving source',Math.min(source-40,w-130),cy+28);return}
if(s.kind==='clock'){let gamma=1/Math.sqrt(1-v*v);for(let n=0;n<2;n++){let a=w*(n?.7:.3),rate=n?1/gamma:1,p=(t*rate*.8)%2,y=45+(p<1?p:2-p)*(h-105);line(x,a-40,40,a+40,40,teal,3);line(x,a-40,h-55,a+40,h-55,teal,3);line(x,a,44,a,h-58,'#c1aacd44',1);dot(x,a,y,6,gold);label(x,n?'moving clock':'rest clock',a-42,h-25)}label(x,'γ = '+gamma.toFixed(2),25,22);return}
if(s.kind==='spectrum'){const peak=2898000/v,values=[];for(let i=0;i<500;i++){let lambda=100+i*4,y=1/(lambda**5*Math.expm1(14387770/(lambda*v)));values.push(y)}let max=Math.max(...values);path(x,u=>h-40-values[Math.min(499,Math.floor(u*499))]/max*(h-90),w,h,gold);let px=30+(peak-100)/2000*(w-60);line(x,px,35,px,h-40,purple,1);dot(x,px,48+Math.sin(t*2)*3,4,teal);label(x,'peak '+Math.round(peak)+' nm',30,24);label(x,'wavelength: 100 → 2100 nm',30,h-15);return}
if(s.kind==='levels'){let yN=n=>h-40-(1-1/(n*n))*(h-90);for(let n=1;n<=5;n++){line(x,50,yN(n),w-65,yN(n),'#79708b',1);label(x,'n='+n,w-55,yN(n)+4)}let p=(t%3)/3,y=yN(v)+(yN(1)-yN(v))*Math.min(1,p*2);dot(x,cx,y,6,teal);if(p>.5){let a=cx+(p-.5)*(w*.8);dot(x,a,yN(1)-Math.sin(a*.1)*7,4,gold)}label(x,'transition '+v+' → 1',30,23);return}
if(s.kind==='decay'){const tt=t%15;let count=0;for(let i=0;i<120;i++){const rand=((i*73+31)%127+1)/128,decay=-Math.log(rand)/Math.LN2*v,alive=tt<decay;if(alive)count++;let a=35+(i%15)*(w-70)/14,b=60+Math.floor(i/15)*(h-100)/7;x.fillStyle=alive?gold:'#3c324c';x.fillRect(a-3,b-3,6,6)}label(x,`t=${tt.toFixed(1)} s  ·  undecayed ${count}/120`,25,25);return}
if(s.kind==='scattering'){dot(x,cx,cy,12,gold);for(let i=0;i<7;i++){let impact=(i-3)*22+6,pts=[],px=30,py=cy+impact,vx=140,vy=0;for(let j=0;j<210;j++){let dx=px-cx,dy=py-cy,r2=dx*dx+dy*dy+60,acc=v*260000/r2**1.5;vx+=dx*acc*.018;vy+=dy*acc*.018;px+=vx*.018;py+=vy*.018;pts.push([px,py])}x.strokeStyle='#b698d777';x.beginPath();pts.forEach((p,j)=>j?x.lineTo(...p):x.moveTo(...p));x.stroke();let p=pts[Math.floor(t*40+i*17)%pts.length];dot(x,...p,3,teal)}label(x,'repulsive nucleus',cx-60,cy+34);return}
if(s.kind==='packet'){let tt=t%6,sigma=v*Math.sqrt(1+(tt/(v*v*3))**2),center=.2+tt*.1;path(x,u=>h-35-Math.exp(-1*((u-center)*7)**2/(2*sigma*sigma))/sigma*h*.6,w,h,purple);label(x,'|ψ|² · normalized units',25,25);return}
if(s.kind==='phasors'){let ax=cx-40,ay=cy+15,start=[ax,ay],phase=t*.35;for(let i=0;i<6;i++){let a=phase+i*v*Math.PI/180,bx=ax+Math.cos(a)*25,by=ay-Math.sin(a)*25;line(x,ax,ay,bx,by,purple,2);dot(x,bx,by,3,purple);ax=bx;ay=by}line(x,...start,ax,ay,gold,3);label(x,'resultant amplitude (gold)',20,h-20,gold);return}
if(s.kind==='symmetry'){let a=Math.min(w*.32,h*.3),angle=v*Math.PI/180,p=t*.9;x.save();x.translate(cx,cy);x.rotate(angle);x.strokeStyle='#bca1de88';x.beginPath();x.ellipse(0,0,a,a*.65,0,0,7);x.stroke();dot(x,0,0,6,gold);dot(x,Math.cos(p)*a,Math.sin(p)*a*.65,6,teal);x.restore();label(x,'Rotate coordinates. Preserve the law.',25,25);return}
if(s.kind==='bose'){let vals=Array.from({length:7},(_,i)=>1/Math.expm1((i*.5+.3)/v)),max=vals[0];for(let i=0;i<7;i++){let a=40+i*(w-75)/7,bh=vals[i]/max*(h-90);x.fillStyle=i?'#a58abc':gold;x.fillRect(a,h-45-bh,(w-100)/10,bh);label(x,'E'+i,a,h-25);dot(x,a+(w-100)/20,h-45-bh+Math.sin(t+i)*3,3,teal)}label(x,'mean state occupation · relative scale',22,22);return}
if(s.kind==='raman'){path(x,u=>{let y=Math.exp(-1*((u-.5)/.013)**2)+.27*Math.exp(-1*((u-(.5-v*.3))/.019)**2)+.12*Math.exp(-1*((u-(.5+v*.3))/.019)**2);return h-45-y*(h-100)},w,h,teal);label(x,'Stokes',Math.max(20,cx-v*.3*(w-60)-25),h-20,gold);label(x,'Rayleigh',cx-27,28);label(x,'anti-Stokes',Math.min(w-95,cx+v*.3*(w-60)-25),h-20,purple);let xx=30+(t*.15%1)*(w-60);dot(x,xx,45,3,gold);return}
if(s.kind==='gas'){let values=Array.from({length:400},(_,i)=>{let vel=i/100;return vel*vel*Math.exp(-vel*vel/(2*v))/v**1.5}),max=Math.max(...values);path(x,u=>h-45-values[Math.min(399,Math.floor(u*399))]/max*(h-100),w,h,gold);for(let i=0;i<18;i++){let a=30+((i*37+t*(20+i*2)*Math.sqrt(v))%(w-60));dot(x,a,30+(i%3)*7,2,teal)}label(x,'speed →',w-90,h-20);return}
if(s.kind==='dirac'){for(let sign of [-1,1])path(x,u=>cy-sign*Math.sqrt(((u-.5)*4)**2+v*v)*h*.15,w,h,sign>0?gold:purple);let p=Math.sin(t*.6)*1.8,a=30+(p/4+.5)*(w-60);for(let sign of [-1,1])dot(x,a,cy-sign*Math.sqrt(p*p+v*v)*h*.15,5,teal);label(x,'+E',25,28,gold);label(x,'−E',25,h-20,purple);return}}
const gameInfo={newton:{title:'Newton’s launch',glyph:'↗',description:'Adjust the angle and speed. Land a probe on three landing pads.',concept:'Projectile motion · three landings'},faraday:{title:'Faraday’s light',glyph:'ε',description:'Move a magnet through a coil. Generate enough energy to light the lab.',concept:'Electromagnetic induction · one lamp'},maxwell:{title:'Maxwell’s signal',glyph:'∿',description:'Tune frequency and phase to match three mysterious incoming waves.',concept:'Wave matching · three signals'},feynman:{title:'Feynman’s photons',glyph:'ψ',description:'Send particles one at a time. Read the pattern and identify the experiment.',concept:'Probability & interference · three rounds'}};
let game=null;
function renderGames(el){el.innerHTML=`<span class="eyebrow">FOUR STOPS ON YOUR PHYSICS JOURNEY</span><h2>Learn the rule.<br>Then play with it.</h2><p>Each challenge earns a stamp for your discovery passport. Progress stays in this browser.</p><div class="game-grid">${Object.entries(gameInfo).map(([id,g],i)=>`<button class="game-card" data-game="${id}"><span class="meta">0${i+1} / ${badges[id]?'STAMP COLLECTED':'READY TO EXPLORE'}</span><span class="science-glyph">${g.glyph}</span><h3>${g.title}</h3><p>${g.description}</p><small>${g.concept}</small></button>`).join('')}</div><p class="passport-message">${Object.values(badges).filter(Boolean).length} / 4 discoveries collected. No timer. Take your time.</p>`}
function openGame(id){if(!gameInfo[id])return;game={id,level:0,time:0,running:false,paused:false,completed:false,attempts:0,angle:45,speed:225,trail:[],x:80,y:320,charge:0,magnet:50,lastDir:0,reversals:0,frequency:2,phase:0,photons:[],batch:0,pending:0};const w=openApp('games');renderGame(w.querySelector('.window-content'))}
function renderGame(el){const g=gameInfo[game.id];el.innerHTML=`<div class="atlas-nav"><button id="arcade-back">‹ All challenges</button><button data-scientist="${game.id}">Explore the science</button></div><span class="eyebrow">THE PHYSICS JOURNEY / ${game.id.toUpperCase()}</span><h2>${g.title}</h2><p class="game-help">${g.description}</p><div class="game-topline"><span id="game-round"></span><span id="game-score"></span></div><canvas id="game-canvas" class="game-canvas" aria-label="${g.title} game area"></canvas><div id="game-inputs"></div><div id="game-status" class="game-status" role="status" aria-live="polite"></div><div class="detail-actions"><button class="filter" id="game-reset">Start over</button><button class="filter" id="game-pause">Pause game</button></div>`;el.scrollTop=0;el.querySelector('#arcade-back').onclick=()=>{game=null;renderGames(el)};el.querySelector('#game-reset').onclick=()=>openGame(game.id);el.querySelector('#game-pause').onclick=e=>{game.paused=!game.paused;e.target.textContent=game.paused?'Resume game':'Pause game'};let inputs=el.querySelector('#game-inputs');
if(game.id==='newton'){inputs.innerHTML=`<div class="game-controls"><label>Angle <input id="launch-angle" type="range" min="20" max="75" value="45"><output id="angle-output">45°</output></label><label>Speed <input id="launch-speed" type="range" min="160" max="320" value="225"><output id="speed-output">225</output></label><button class="primary" id="launch">Launch probe</button></div>`;inputs.querySelector('#launch-angle').oninput=e=>{game.angle=+e.target.value;inputs.querySelector('#angle-output').value=game.angle+'°'};inputs.querySelector('#launch-speed').oninput=e=>{game.speed=+e.target.value;inputs.querySelector('#speed-output').value=game.speed};inputs.querySelector('#launch').onclick=()=>{if(game.running||game.completed)return;game.time=0;game.x=80;game.y=320;game.vx=game.speed*Math.cos(game.angle*Math.PI/180);game.vy=-game.speed*Math.sin(game.angle*Math.PI/180);game.trail=[];game.running=true;paused=false;motionLabel();game.attempts++;game.paused=false;inputs.querySelector('#launch').disabled=true;setGameStatus('Probe in flight. Gravity is doing its thing.');updateGameHud()};setGameStatus('Land on the glowing pad. Range grows with speed; 45° maximizes range on level ground.');}
if(game.id==='faraday'){inputs.innerHTML=`<div class="game-controls"><label>Magnet position <input id="magnet-position" type="range" min="0" max="100" value="50"><output id="magnet-output">50</output></label><button class="filter" id="magnet-left">Move left</button><button class="filter" id="magnet-right">Move right</button></div><div class="meter" aria-label="Lamp charge"><span id="charge-fill"></span></div>`;function move(value){if(game.completed||game.paused)return;let delta=value-game.magnet,dir=Math.sign(delta);if(dir&&game.lastDir&&dir!==game.lastDir)game.reversals++;if(dir)game.lastDir=dir;game.charge=Math.min(100,game.charge+Math.abs(delta)*.28);game.magnet=value;game.impulse=Math.min(1,Math.abs(delta)/15);inputs.querySelector('#magnet-position').value=value;inputs.querySelector('#magnet-output').value=value;inputs.querySelector('#charge-fill').style.width=game.charge+'%';updateGameHud();if(game.charge>=100&&game.reversals>=3)winGame();else setGameStatus('Keep moving the magnet back and forth. A stationary magnet produces no changing flux.')}inputs.querySelector('#magnet-position').oninput=e=>move(+e.target.value);inputs.querySelector('#magnet-left').onclick=()=>move(Math.max(0,game.magnet-25));inputs.querySelector('#magnet-right').onclick=()=>move(Math.min(100,game.magnet+25));setGameStatus('Charge the lamp to 100% and reverse direction at least three times. Stored energy is a simplified game mechanic.');}
if(game.id==='maxwell'){inputs.innerHTML=`<div class="game-controls"><label>Frequency <input id="wave-frequency" type="range" min="1" max="4" step="0.1" value="2"><output id="freq-output">2.0</output></label><label>Phase <input id="wave-phase" type="range" min="0" max="350" step="10" value="0"><output id="phase-output">0°</output></label><button class="primary" id="lock-signal">Lock signal</button></div>`;inputs.querySelector('#wave-frequency').oninput=e=>{game.frequency=+e.target.value;inputs.querySelector('#freq-output').value=game.frequency.toFixed(1);updateGameHud()};inputs.querySelector('#wave-phase').oninput=e=>{game.phase=+e.target.value;inputs.querySelector('#phase-output').value=game.phase+'°';updateGameHud()};inputs.querySelector('#lock-signal').onclick=()=>{if(game.completed)return;const tar=waveTarget();if(Math.abs(game.frequency-tar[0])<.051&&Math.abs(game.phase-tar[1])<6){game.level++;if(game.level===3)winGame();else setGameStatus('Signal locked! A new wave is arriving. Match this one next.')}else setGameStatus('Not quite aligned. Frequency changes the spacing; phase slides the wave.');updateGameHud()};setGameStatus('Match the gold incoming wave with your purple wave, then lock the signal.');}
if(game.id==='feynman'){inputs.innerHTML=`<div class="game-controls"><button class="primary" id="send-photons">Send 100 photons</button><button class="filter" id="guess-single">One slit</button><button class="filter" id="guess-double">Two slits</button></div>`;inputs.querySelector('#send-photons').onclick=()=>{if(!game.completed){game.pending+=100;game.running=true;paused=false;motionLabel()}};inputs.querySelector('#guess-single').onclick=()=>guessPhotons(false);inputs.querySelector('#guess-double').onclick=()=>guessPhotons(true);setGameStatus('Send photons, then infer the setup from the detection pattern. Two slits add clear interference fringes.');}
updateGameHud()}
function setGameStatus(msg,success=false){const e=document.querySelector('#game-status');if(e){e.textContent=msg;e.classList.toggle('success',success)}}
function updateGameHud(){if(!game)return;const round=document.querySelector('#game-round'),score=document.querySelector('#game-score');if(!round||!score)return;round.textContent=game.completed?'DISCOVERY COMPLETE':game.id==='faraday'?'CHARGE THE LAB':'ROUND '+Math.min(3,game.level+1)+' / 3';score.textContent=game.id==='newton'?'LAUNCHES '+game.attempts:game.id==='faraday'?Math.round(game.charge)+'% CHARGE · '+game.reversals+' REVERSALS':game.id==='maxwell'?'SIGNAL MATCH '+waveMatch()+'%':game.photons.length+' DETECTIONS'}
function winGame(){game.completed=true;game.running=false;award(game.id);setGameStatus('Discovery collected! '+gameInfo[game.id].title+' stamp added to your passport. Explore another challenge when you’re ready.',true);updateGameHud()}
function waveTarget(){return [[2.4,60],[3.2,120],[1.6,210]][Math.min(game.level,2)]}
function waveMatch(){const tar=waveTarget();let err=0;for(let i=0;i<100;i++){const u=i/100;err+=(Math.sin(u*Math.PI*2*game.frequency+game.phase*Math.PI/180)-Math.sin(u*Math.PI*2*tar[0]+tar[1]*Math.PI/180))**2}return Math.max(0,Math.round((1-Math.sqrt(err/100)/1.5)*100))}
function photonIntensity(u,double){const z=(u-.5)*6,alpha=Math.PI*.42*z,env=Math.abs(alpha)<.001?1:(Math.sin(alpha)/alpha)**2;return env*(double?Math.cos(Math.PI*2*z)**2:1)}
function addPhoton(){const double=[true,false,true][game.level];let u=0;for(let tries=0;tries<10000;tries++){u=Math.random();if(Math.random()<photonIntensity(u,double))break}game.photons.push({u,y:Math.random()})}
function guessPhotons(double){if(game.completed)return;if(game.photons.length<100){setGameStatus('Collect at least 100 detections before choosing. One photon alone cannot reveal the full pattern.');return}if(double===[true,false,true][game.level]){game.level++;if(game.level===3){winGame();return}game.photons=[];game.pending=0;setGameStatus('Correct! A new hidden setup is ready. Gather another detection pattern.')}else setGameStatus('Look again: evenly spaced dark gaps point to two-slit interference. You can send more photons.');updateGameHud()}
function drawGame(dt){const c=document.querySelector('#game-canvas');if(!c||!game||wins.get('games')?.hidden)return;const step=(game.paused||paused)?0:dt;const[w,h,x]=fit(c);x.clearRect(0,0,w,h);x.save();x.scale(w/1000,h/400);x.font='16px monospace';const gold='#e5cb86',purple='#cbb1f4',teal='#91d3cb';for(let a=30;a<1000;a+=45){line(x,a,30,a,370,'#88709e18',1)}for(let b=30;b<380;b+=45)line(x,25,b,975,b,'#88709e18',1);
if(game.id==='newton'){const target=[490,660,790][Math.min(game.level,2)];line(x,25,340,975,340,'#6f7c79',3);x.fillStyle=teal;x.fillRect(target-35,331,70,12);x.fillStyle='#446254';x.fillRect(target-35,343,70,8);label(x,'LAND HERE',target-32,370,teal);line(x,80,320,80+Math.cos(game.angle*Math.PI/180)*40,320-Math.sin(game.angle*Math.PI/180)*40,gold,7);if(game.running&&step){game.time+=step;game.x+=game.vx*step;game.vy+=100*step;game.y+=game.vy*step;game.trail.push([game.x,game.y]);if((game.y>=326&&game.time>.3)||game.x>1000){game.running=false;document.querySelector('#launch').disabled=false;if(Math.abs(game.x-target)<=35){game.level++;if(game.level===3)winGame();else{setGameStatus('A clean landing! Next pad is farther away. Adjust and launch again.',true);game.x=80;game.y=320}}else setGameStatus(game.x<target?'A little short. Try more speed.':'Overshot. Try less speed or a different angle.');updateGameHud()}}x.fillStyle='#ab90cd';for(let i=0;i<game.trail.length;i+=5){let p=game.trail[i];x.fillRect(p[0]-2,p[1]-2,4,4)}dot(x,game.x,Math.min(327,game.y),7,gold);label(x,'g = 100 · normalized game units',30,28);}
if(game.id==='faraday'){game.time+=step;game.impulse=Math.max(0,(game.impulse||0)-step*1.5);let mx=100+game.magnet*6;for(let i=0;i<9;i++){x.strokeStyle=purple;x.lineWidth=4;x.beginPath();x.ellipse(490+i*9,200,18,65,0,0,7);x.stroke()}x.fillStyle='#b77893';x.fillRect(mx-45,180,45,40);x.fillStyle='#86b3c4';x.fillRect(mx,180,45,40);label(x,'N',mx-29,205,'#131324');label(x,'S',mx+18,205,'#131324');line(x,565,145,860,145,'#7c6a8d',3);line(x,860,145,860,235,'#7c6a8d',3);line(x,860,265,860,305,'#7c6a8d',3);line(x,860,305,490,305,'#7c6a8d',3);line(x,490,305,490,260,'#7c6a8d',3);dot(x,860,250,25,game.completed?gold:'#554b5d');if(game.completed){x.strokeStyle=gold;for(let i=0;i<12;i++){let a=i*Math.PI/6;line(x,860+Math.cos(a)*35,250+Math.sin(a)*35,860+Math.cos(a)*46,250+Math.sin(a)*46,gold,2)}}for(let i=0;i<6;i++)if(game.impulse>.05)dot(x,570+((game.time*150+i*45)%285),145,4,teal);label(x,'MOVE THE MAGNET THROUGH THE COIL',270,65);label(x,'energy '+Math.round(game.charge)+'%',800,360,gold);}
if(game.id==='maxwell'){game.time+=step;const tar=waveTarget();for(let n=0;n<2;n++){let f=n?game.frequency:tar[0],phase=n?game.phase:tar[1];x.strokeStyle=n?purple:gold;x.lineWidth=n?3:2;x.setLineDash(n?[]:[8,6]);x.beginPath();for(let a=30;a<=970;a++){let u=(a-30)/940,y=200-Math.sin(u*Math.PI*2*f+phase*Math.PI/180-game.time)*95;a===30?x.moveTo(a,y):x.lineTo(a,y)}x.stroke();x.setLineDash([])}label(x,'incoming signal (gold) · your signal (purple)',32,35);}
if(game.id==='feynman'){if(step&&game.pending>0&&!game.completed){game.batch+=step*180;while(game.batch>=1&&game.pending>0){addPhoton();game.pending--;game.batch--}updateGameHud()}x.strokeStyle='#71607d';x.strokeRect(35,55,930,170);x.fillStyle='#d7b8ef';for(const p of game.photons){x.fillRect(36+p.u*928,56+p.y*168,3,3)}let bins=Array(70).fill(0);game.photons.forEach(p=>bins[Math.min(69,Math.floor(p.u*70))]++);let max=Math.max(1,...bins);x.fillStyle=gold;bins.forEach((n,i)=>{let bh=n/max*110;x.fillRect(35+i*930/70,365-bh,930/70-2,bh)});label(x,'DETECTION SCREEN · one event at a time',35,30);label(x,'observed counts',35,390);}
x.restore()}
(function registerDiscoveryTool(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(context.registerTool({name:'open_physics_discovery',title:'Open a physics discovery',description:'Open a scientist’s educational animation in the visible portfolio and optionally set its parameter. Does not change passport progress.',inputSchema:{type:'object',properties:{scientist:{type:'string',enum:scientists.map(s=>s.id)},parameter:{type:'number'}},required:['scientist'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['scientist','parameter'].includes(k)))throw new Error('Invalid input');const s=scientists.find(s=>s.id===input.scientist);if(!s)throw new Error('Unknown scientist');if(input.parameter!==undefined&&(typeof input.parameter!=='number'||!Number.isFinite(input.parameter)||input.parameter<s.min||input.parameter>s.max))throw new Error('Parameter outside the allowed range');openScientist(s.id);if(input.parameter!==undefined){discovery.value=Math.max(s.min,Math.min(s.max,Math.round((input.parameter-s.min)/s.step)*s.step+s.min));document.querySelector('#science-range').value=discovery.value;document.querySelector('#science-value').value=Number(discovery.value.toFixed(3))}return{scientist:s.name,parameter:discovery.value,title:s.title}}},{signal:lifecycle.signal})).catch(()=>{})}catch{}})();
